package com.tekwatt.reporting.service;
import com.fasterxml.jackson.databind.JsonNode;import com.tekwatt.reporting.entity.ReportType;import java.nio.charset.StandardCharsets;import java.util.*;import org.springframework.stereotype.Component;
@Component public class HtmlReportGenerator {public byte[] generate(ReportType type,JsonNode data){List<JsonNode> rows=new ArrayList<>();if(type==ReportType.DAILY&&data.isArray())data.forEach(rows::add);else rows.add(data);LinkedHashSet<String> headers=new LinkedHashSet<>();rows.forEach(row->row.fieldNames().forEachRemaining(headers::add));StringBuilder html=new StringBuilder("<!doctype html><html lang=\"en\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><title>TekWatt ").append(type.name()).append(" Report</title><style>body{font-family:Arial,sans-serif;color:#172033;margin:32px}h1{color:#096b5c}table{border-collapse:collapse;width:100%;margin-top:20px}th,td{border:1px solid #d7dee8;padding:10px;text-align:left}th{background:#eaf7f4}tr:nth-child(even){background:#f8fafc}@media print{body{margin:12mm}}</style></head><body><h1>TekWatt ").append(type.name()).append(" Report</h1><table><thead><tr>");headers.forEach(h->html.append("<th>").append(escape(h)).append("</th>"));html.append("</tr></thead><tbody>");for(JsonNode row:rows){html.append("<tr>");headers.forEach(h->html.append("<td>").append(escape(row.path(h).isMissingNode()?"":row.path(h).asText())).append("</td>"));html.append("</tr>");}return html.append("</tbody></table></body></html>").toString().getBytes(StandardCharsets.UTF_8);}private String escape(String value){return value.replace("&","&amp;").replace("<","&lt;").replace(">","&gt;").replace("\"","&quot;").replace("'","&#39;");}}
